-- V109 exact required-control readiness certification for tenant activation.
CREATE TABLE IF NOT EXISTS onboarding_control_sets(tenant_id text NOT NULL,control_set_key text NOT NULL,version integer NOT NULL CHECK(version>=1),definition_hash char(64) NOT NULL,required_controls jsonb NOT NULL,defined_by_hash char(64) NOT NULL,defined_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,control_set_key,version));CREATE TABLE IF NOT EXISTS onboarding_evidence(tenant_id text NOT NULL,control_set_key text NOT NULL,control_set_version integer NOT NULL,control_key text NOT NULL,status text NOT NULL CHECK(status IN('PASS','FAIL')),evidence_hash char(64) NOT NULL,recorded_by_hash char(64) NOT NULL,recorded_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,control_set_key,control_set_version,control_key));CREATE TABLE IF NOT EXISTS onboarding_certifications(id text PRIMARY KEY,tenant_id text NOT NULL,control_set_key text NOT NULL,control_set_version integer NOT NULL,definition_hash char(64) NOT NULL,readiness_evidence_hash char(64) NOT NULL UNIQUE,certified_by_hash char(64) NOT NULL,certified_at timestamptz NOT NULL);ALTER TABLE onboarding_control_sets ENABLE ROW LEVEL SECURITY;ALTER TABLE onboarding_control_sets FORCE ROW LEVEL SECURITY;ALTER TABLE onboarding_evidence ENABLE ROW LEVEL SECURITY;ALTER TABLE onboarding_evidence FORCE ROW LEVEL SECURITY;ALTER TABLE onboarding_certifications ENABLE ROW LEVEL SECURITY;ALTER TABLE onboarding_certifications FORCE ROW LEVEL SECURITY;CREATE POLICY onboarding_set_tenant ON onboarding_control_sets USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY onboarding_evidence_tenant ON onboarding_evidence USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY onboarding_cert_tenant ON onboarding_certifications USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
